const config = window.PROSPETT_CONFIG || {};
const menu = document.querySelector('.menu');
menu?.addEventListener('click', () => { const open = menu.getAttribute('aria-expanded') !== 'true'; menu.setAttribute('aria-expanded', String(open)); menu.setAttribute('aria-label', open ? 'Fechar menu' : 'Abrir menu'); document.querySelector('#navigation').classList.toggle('open', open); });
document.querySelectorAll('#navigation a').forEach(a => a.addEventListener('click', () => { menu.setAttribute('aria-expanded', 'false'); menu.setAttribute('aria-label', 'Abrir menu'); document.querySelector('#navigation').classList.remove('open'); }));
document.addEventListener('keydown', e => { if(e.key === 'Escape' && menu?.getAttribute('aria-expanded') === 'true') { menu.click(); menu.focus(); } });
const steps = [
['A atenção vira uma visita.', 'Conteúdo, buscas e campanhas levam pessoas às páginas da empresa. A equipe define a mensagem; a mensuração ajuda a entender de onde vêm os acessos.', 'ESTRATÉGIA + MENSURAÇÃO'],
['Uma visita abre uma conversa.', 'O formulário registra o interesse e encaminha os dados necessários. A confirmação depende de uma integração ativa; a equipe define a abordagem e o prazo de retorno.', 'CAPTURA + CONTEXTO'],
['Cada oportunidade ganha contexto.', 'Regras aprovadas organizam os contatos por interesse e momento de compra. A equipe revisa exceções e valida os critérios de qualificação.', 'AUTOMAÇÃO + REVISÃO HUMANA'],
['O contato chega ao lugar certo.', 'A integração registra a oportunidade no CRM, atribui um responsável e organiza o histórico. A equipe comercial acompanha e mantém as informações atualizadas.', 'INTEGRAÇÃO + RESPONSABILIDADE'],
['Relacionamento com continuidade.', 'Lembretes e comunicações autorizadas ajudam a manter o acompanhamento. A equipe conduz as conversas, entende necessidades e aprova mensagens e propostas.', 'LEMBRETES + RELACIONAMENTO'],
['O aprendizado orienta a próxima ação.', 'Indicadores mostram como os contatos avançam. A equipe interpreta os dados, identifica obstáculos e ajusta campanhas, conteúdos e fluxos.', 'DADOS + DECISÃO HUMANA']];
const tabs = [...document.querySelectorAll('[data-step]')];
function selectStep(i) { tabs.forEach((tab, n) => { tab.setAttribute('aria-selected', String(n === i)); tab.tabIndex = n === i ? 0 : -1; }); const panel = document.querySelector('#flow-panel'); panel.setAttribute('aria-labelledby', 'step-' + i); panel.querySelector('.step-number').textContent = `0${i+1} / 06`; panel.querySelector('h3').textContent = steps[i][0]; panel.querySelector('p').textContent = steps[i][1]; panel.querySelector('.flow-tag').textContent = steps[i][2]; }
tabs.forEach((tab, i) => { tab.addEventListener('click', () => selectStep(i)); tab.addEventListener('keydown', e => { let next; if(e.key === 'ArrowRight') next=(i+1)%6; if(e.key === 'ArrowLeft') next=(i+5)%6; if(e.key === 'Home') next=0; if(e.key === 'End') next=5; if(next !== undefined) {e.preventDefault(); selectStep(next); tabs[next].focus();} }); });
if ('IntersectionObserver' in window && !matchMedia('(prefers-reduced-motion: reduce)').matches) { const observer = new IntersectionObserver(entries => entries.forEach(entry => { if(entry.isIntersecting) {entry.target.classList.add('visible'); observer.unobserve(entry.target);} }), {threshold: .08}); document.querySelectorAll('.reveal').forEach(el => {el.classList.add('will-reveal');observer.observe(el);}); }
function track(name) { if(config.analyticsEnabled) window.dispatchEvent(new CustomEvent('prospett:conversion', {detail:{event:name}})); }
document.querySelectorAll('a[href="#diagnostico"]').forEach(a => a.addEventListener('click', () => track('diagnostic_cta')));
const number = (config.whatsapp || '').replace(/\D/g, '');
if(/^55\d{10,11}$/.test(number)) document.querySelectorAll('[data-contact]').forEach(a => {a.href='https://wa.me/'+number; a.rel='noopener noreferrer';});
const form = document.querySelector('#diagnostic-form');
form?.addEventListener('submit', async e => { e.preventDefault(); if(!form.reportValidity()) return; const status = document.querySelector('#form-status'); const button = form.querySelector('button[type="submit"]'); const data = Object.fromEntries(new FormData(form)); if(data.fax) return; delete data.fax;
if(!config.formEndpoint) { status.textContent = 'O envio está temporariamente indisponível. Seus dados não foram enviados. Tente novamente quando o canal de atendimento estiver disponível.'; status.dataset.state='error'; return; }
const phone = data.phone.replace(/\D/g, ''); if(phone && (phone.length<10 || phone.length>13)) { status.textContent='Confira o WhatsApp e inclua o DDD.'; form.elements.phone.focus(); return; }
button.disabled=true; button.textContent='Enviando…'; status.textContent='Enviando sua solicitação com segurança.'; status.dataset.state='pending';
try { const endpoint = new URL(config.formEndpoint, location.origin); if(endpoint.protocol !== 'https:' && endpoint.origin !== location.origin) throw new Error('Invalid endpoint'); const response = await fetch(endpoint, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(data), signal:AbortSignal.timeout(15000)}); if(!response.ok) throw new Error('Request failed'); status.textContent='Solicitação enviada. A Prospétt entrará em contato para conversar sobre seu diagnóstico.'; status.dataset.state='success'; form.reset(); track('diagnostic_submitted'); } catch { status.textContent='Não foi possível confirmar o envio. Seus dados foram mantidos no formulário. Tente novamente em instantes.'; status.dataset.state='error'; } finally {button.disabled=false; button.innerHTML='Solicitar diagnóstico <span>↗</span>';} });
document.querySelectorAll('[data-privacy-contact]').forEach(el => { if(config.privacyContact) el.textContent=config.privacyContact; });
if(document.querySelector('#year')) document.querySelector('#year').textContent=new Date().getFullYear();
